:root {
  --bg: #fffaf7;
  --border: #f0e6dd;
  --header-bg: #f9e8da;
  --title-color: #3b2315;
  --icon-color: #c9703a;
  --streak-bg: #fff0e6;
  --streak-color: #b85c28;
  --done-bg: #f0faf3;
  --done-border: #b6e2c4;
  --done-num: #3a7d52;
  --done-name: #2d5e3e;
  --done-type: #7ab994;
  --done-badge-bg: #b6e2c4;
  --done-badge-color: #2d5e3e;
  --active-bg: #fff8ee;
  --active-border: #f5c18a;
  --active-num: #c9703a;
  --active-name: #3b2315;
  --active-type: #c9703a;
  --active-badge-bg: #f5c18a;
  --active-badge-color: #7a3a10;
  --pending-bg: #fafafa;
  --pending-border: #e8ddd6;
  --pending-num: #c0a899;
  --pending-name: #7a6058;
  --pending-type: #b0998e;
  --pending-badge-bg: #ede5e0;
  --pending-badge-color: #9a7a6e;
  --footer-label: #a08070;
  --progress-track: #f0e0d4;
  --progress-fill: #c9703a;
}

.tracker {
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 20px;
  width: 480px;
  padding: 0;
  overflow: hidden;
}

.tracker-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  border-bottom: 2px solid var(--border);
}

.header-icon {
  color: var(--icon-color);
  font-size: 18px;
}

.tracker-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--title-color);
  flex: 1;
  margin: 0;
}

.tracker-streak {
  font-size: 13px;
  font-weight: 600;
  background: var(--streak-bg);
  color: var(--streak-color);
  border-radius: 20px;
  padding: 4px 12px;
  border: 1px solid var(--active-border);
}

.steps-grid {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 12px 16px;
  gap: 8px;
}

.step {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1.5px solid var(--pending-border);
  background: var(--pending-bg);
}

.step.done {
  background: var(--done-bg);
  border-color: var(--done-border);
}

.step.active {
  background: var(--active-bg);
  border-color: var(--active-border);
}

.step.pending {
  background: var(--pending-bg);
  border-color: var(--pending-border);
}

.step-num {
  font-size: 12px;
  font-weight: 700;
  color: var(--pending-num);
  min-width: 22px;
}

.step.done .step-num {
  color: var(--done-num);
}

.step.active .step-num {
  color: var(--active-num);
}

.step-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.step-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--pending-name);
}

.step.done .step-name {
  color: var(--done-name);
}

.step.active .step-name {
  color: var(--active-name);
}

.step-type {
  font-size: 11px;
  font-weight: 400;
  color: var(--pending-type);
}

.step.done .step-type {
  color: var(--done-type);
}

.step.active .step-type {
  color: var(--active-type);
}

.step-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  background: var(--pending-badge-bg);
  color: var(--pending-badge-color);
}

.step.done .step-badge {
  background: var(--done-badge-bg);
  color: var(--done-badge-color);
}

.step.active .step-badge {
  background: var(--active-badge-bg);
  color: var(--active-badge-color);
}

.tracker-footer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px 16px;
}

.progress-bar-wrap {
  flex: 1;
  height: 8px;
  background: var(--progress-track);
  border-radius: 8px;
  overflow: hidden;
}

.progress-bar-fill {
  width: 40%;
  height: 100%;
  background: var(--progress-fill);
  border-radius: 8px;
}

.progress-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--footer-label);
  white-space: nowrap;
}
